class T3ma_api(API_base):
    """
    Fetches the Triple Exponential Moving Average (T3MA) for a given financial instrument.
    """
    def __init__(self):
        pass

    def execute(self, **params):
        expected_params = set(["symbol_", "interval_", "format_", "v_factor_", "series_type_", "outputsize_", "time_period_"])
