        symbol_ = params.get('symbol_', None)
        if symbol_ is not None:
            is_valid, error = self.validate_type(symbol_, 'symbol_', str)
            if not is_valid:
                return error
        if symbol_ is not None:
            symbol_ = symbol_.lower()
        
