class Options_prices_api(API_base):
    """
    Fetch current options data given the input parameters.
    """
    def __init__(self):
        pass

    def execute(self, **params):
        expected_params = set(["type_", "symbol_", "min_strike_", "min_expiry_", "max_expiry_", "max_strike_", "strike_", "expiration_"])
        unexpected_params = set(params.keys()) - expected_params 
        if unexpected_params:
            return self.handle_error(f"Unexpected parameters: {', '.join(unexpected_params)}", 400)
        type_ = params.get('type_', None)
        if type_ is not None:
            is_valid, error = self.validate_type(type_, 'type_', str)
            if not is_valid:
                return error
        if type_ is not None:
            type_ = type_.lower()
        
        symbol_ = params.get('symbol_', None)
        if symbol_ is not None:
            is_valid, error = self.validate_type(symbol_, 'symbol_', str)
            if not is_valid:
                return error
        if symbol_ is not None:
            symbol_ = symbol_.lower()
        
        _default_min_strike_ = int("50") if "50" !=  ""  else 0
        min_strike_ = params.get('min_strike_', _default_min_strike_)
        if min_strike_ is not None:
            is_valid, error = self.validate_type(min_strike_, 'min_strike_', int)
            if not is_valid:
                return error
        
        min_expiry_ = params.get('min_expiry_', "2021-05-21")
        if min_expiry_ is not None:
            is_valid, error = self.validate_type(min_expiry_, 'min_expiry_', str)
            if not is_valid:
                return error
        if min_expiry_ is not None:
            min_expiry_ = min_expiry_.lower()
        
        max_expiry_ = params.get('max_expiry_', "2023-12-14")
        if max_expiry_ is not None:
            is_valid, error = self.validate_type(max_expiry_, 'max_expiry_', str)
            if not is_valid:
                return error
        if max_expiry_ is not None:
            max_expiry_ = max_expiry_.lower()
        
        _default_max_strike_ = int("90") if "90" !=  ""  else 0
        max_strike_ = params.get('max_strike_', _default_max_strike_)
        if max_strike_ is not None:
            is_valid, error = self.validate_type(max_strike_, 'max_strike_', int)
            if not is_valid:
                return error
        
        _default_strike_ = float(50) if 50 != "" else 0.0
        strike_ = params.get('strike_', _default_strike_)
        if strike_ is not None:
            is_valid, error = self.validate_type(strike_, 'strike_', (float, int))
            if not is_valid:
                return error
        if strike_ is not None:
            strike_ = float(strike_)
        
        expiration_ = params.get('expiration_', "2023-12-14")
        if expiration_ is not None:
            is_valid, error = self.validate_type(expiration_, 'expiration_', str)
            if not is_valid:
                return error
        if expiration_ is not None:
            expiration_ = expiration_.lower()
        
        return {
            "status_code": 200, 
            "results": {
                "function_name": "Options_prices_api",
                "type_": type_,
                "symbol_": symbol_,
                "min_strike_": min_strike_,
                "min_expiry_": min_expiry_,
                "max_expiry_": max_expiry_,
                "max_strike_": max_strike_,
                "strike_": strike_,
                "expiration_": expiration_
            }
        }

